+            throw new RuntimeException("Template resource not found: " + e.getMessage(), e);
+        } catch (Exception e) {
+            // Catch any other unexpected errors during rendering
+            throw new RuntimeException("Unexpected error during template rendering: " + e.getMessage(), e);
+        }
+
+        return writer.toString();
+    }
